LABELS={'needs_review':'Ready for review','plan_review':'Plan needs approval','quality_blocked':'Needs correction','budget_blocked':'Request limit reached','dependency_blocked':'Dependency blocked','plan_failed':'Planning stopped','active':'In progress','approved':'Approved','new':'Ready to plan','pending':'Not started','failed':'Stopped','rejected':'Changes requested','running':'Working','interrupted':'Interrupted'}
def badge(status):
    kind='review' if status in ('needs_review','plan_review') else 'blocked' if status in ('quality_blocked','budget_blocked','dependency_blocked','failed','plan_failed','rejected','interrupted') else 'done' if status=='approved' else 'active' if status in ('active','running') else ''
    return '<span class="status '+kind+'">'+esc(LABELS.get(status,status.replace('_',' ')))+'</span>'

def page(body,title='Workspace',active='projects'):
    # Keep diagnostic JSON and worker commands available without crowding the draft.
    body=re.sub(r'<pre>(\{.*?\})</pre>',r'<details><summary>Technical check details</summary><pre>\1</pre></details>',body,flags=re.S)
    body=re.sub(r'<p>Worker command: (.*?)</p>',r'<details><summary>Run work from the terminal</summary><p>Worker command: \1</p></details>',body,flags=re.S)
    for status in LABELS:
        body=body.replace('<strong>'+status+'</strong>',badge(status))
    nav=''.join('<a href="'+url+'"'+(' aria-current="page"' if key==active else '')+'><span class="nav-icon" aria-hidden="true">'+icon+'</span>'+label+'</a>' for key,url,icon,label in [('overview','/','◈','Overview'),('projects','/projects','▦','Projects'),('queue','/queue','☷','Task queue')])
    return HTMLResponse('<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'+esc(title)+' | Superhuman</title><style>'+STYLE+'</style></head><body><a class="sr-only" href="#main">Skip to content</a><aside class="sidebar"><a class="brand" href="/">superhuman<em>·</em><small>YOUR PERSONAL WORKSPACE</small></a><nav aria-label="Main navigation">'+nav+'</nav><footer><p><span class="privacy"></span>Local workspace</p><p>Built around how you think.<br>One useful step at a time.</p></footer></aside><div class="workspace"><header class="topbar"><div class="breadcrumb">WORKSPACE / '+esc(active.upper())+'</div><div class="avatar" aria-label="Mahnoor Sarwar">MS</div></header><main id="main"><div class="'+('review-layout' if 'Project review' in title or title=='Revision checks' else '')+'">'+body+'</div><footer class="page-footer">Superhuman Studio · Local project workspace · Review decisions stay with you</footer></main></div></body></html>')

# Existing review functions keep their behavior and adopt the new renderer.
review.web.page=page
base.page=lambda body,title='Task queue':page(body,title,'queue')

# Preserve all mutation routes. Replace only the two listing views.
app.router.routes[:]=[route for route in app.router.routes if not(getattr(route,'path','') in ('/','/projects') and 'GET' in getattr(route,'methods',set()))]

def cards(projects):
    result=''
    for p in projects:
        approved=sum(t['status']=='approved' for t in p.get('tasks',[]));total=len(p.get('tasks',[]))
        if 'tasks' not in p:
            full=e.get(p['id']);approved=sum(t['status']=='approved' for t in full['tasks']);total=len(full['tasks'])
        percent=int(100*approved/total) if total else 0
        result+='<article class="project-card"><div class="card-meta"><span class="workstream">'+esc(p['workstream'].replace('_',' '))+'</span>'+badge(p['status'])+'</div><h3><a href="/projects/'+esc(p['id'])+'">'+esc(p['objective'])+'</a></h3><p class="description">'+esc((p.get('details') or 'Open this project to view its plan and next steps.')[:190])+'</p><div class="progress" role="img" aria-label="'+str(approved)+' of '+str(total)+' tasks approved"><i style="width:'+str(percent)+'%"></i></div><div class="card-meta"><span>'+str(approved)+' / '+str(total)+' tasks approved</span><span>'+str(p['used_calls'])+' / '+str(p['max_calls'])+' API attempts</span></div><div><a class="button secondary" href="/projects/'+esc(p['id'])+'">Open project →</a></div></article>'
    return '<div class="project-grid">'+result+'</div>' if result else '<div class="empty"><strong>Space for your next useful step.</strong>Create a project with a clear outcome and the context it needs.</div>'

def all_projects():
    return sorted(e.listing(),key=lambda p: p.get('updated_at',''),reverse=True)

@app.get('/')
def overview():
    projects=all_projects();attention=[p for p in projects if p['status'] in ('needs_review','plan_review','budget_blocked','dependency_blocked','plan_failed','rejected')]
    # A project can be active while a particular task is blocked or awaiting review.
    for p in projects:
        if p not in attention and any(t['status'] in ('quality_blocked','needs_review','failed','interrupted') for t in e.get(p['id'])['tasks']):attention.append(p)
    active=sum(p['status']=='active' for p in projects);done=sum(p['status']=='approved' for p in projects)
    stats=''.join('<div class="stat '+('attention' if i==0 else '')+'"><span>'+label+'</span><b>'+str(value)+'</b></div>' for i,(label,value) in enumerate([('Needs your attention',len(attention)),('In progress',active),('Approved projects',done),('Total projects',len(projects))]))
    next_step=('<div class="next-step"><div><strong>Your next decision is ready.</strong><p>Start with the projects that need a review or correction.</p></div><a class="button" href="/projects/'+esc(attention[0]['id'])+'">Review project →</a></div>') if attention else '<div class="next-step"><div><strong>A clear view of what comes next.</strong><p>Create a project, define the outcome, then review its plan before work begins.</p></div><a class="button" href="/projects#new-project">Create project →</a></div>'
    return page('<div class="eyebrow">Your command center</div><div class="lead-row"><div><h1>Make room for the work that matters.</h1><p class="intro">Your projects, decisions and drafts in one place. Start with what needs your attention.</p></div><a class="button" href="/projects#new-project">＋ New project</a></div><div class="cards">'+stats+'</div>'+next_step+'<div class="section-head"><h2>'+('Needs your attention' if attention else 'Recent projects')+'</h2><a href="/projects">View all projects →</a></div>'+cards((attention or projects)[:6]),'Overview','overview')

@app.get('/projects')
def projects():
    rows=all_projects()
    options=''.join('<option value="'+esc(k)+'">'+esc(v['name'])+'</option>' for k,v in base.WORKSTREAMS.items())
    form='<details id="new-project"><summary>＋ Create a new project</summary><p class="muted">Describe the result you need. Creating a project makes no API request.</p><form method="post" action="/projects"><label>Workstream<select name="workstream">'+options+'</select></label><label>What do you want to achieve?<input name="objective" maxlength="1000" required placeholder="For example: prepare our university discovery pack"></label><label>What should Superhuman know?<textarea name="details" maxlength="12000" placeholder="Background, sources, constraints and what a useful result should contain"></textarea></label><label>Maximum API attempts<input name="max_calls" type="number" min="1" max="100" value="12"></label><p class="muted">This limits request attempts, including failed requests. It is not a cash budget. Planning and workers can use these requests.</p><button>Create project</button></form></details>'
    return page('<div class="eyebrow">From intention to progress</div><h1>Your projects</h1><p class="intro">Give each outcome a home. Keep its context, drafts and decisions together.</p>'+form+'<div class="section-head"><h2>All projects <span class="muted">('+str(len(rows))+')</span></h2></div>'+cards(rows),'Projects')

@app.get('/queue')
def task_queue():return base.home()
